type Request struct {
	WorkspaceRoot string
	Reports       []string
}

type Result struct {
	Reports    []ReportResult         `json:"reports"`
	Unresolved []UnresolvedDiagnostic `json:"unresolved,omitempty"`
	Status     Status                 `json:"status"`
}

type Status string

