)

const (
	ExitOK         = 0
	ExitError      = 1
	ExitUsage      = 2
	ExitConfig     = 3
	ExitWorkspace  = 4
	ExitValidation = 5
	ExitRuntime    = 6
	ExitCancel     = 7
	ExitPartial    = 8
)

type Config struct {
	Args                 []string
	Stdin                io.Reader
	Stdout               io.Writer
	Stderr               io.Writer
	Context              context.Context
	Version              Version
	WorkDir              string
	Env                  map[string]string
	TUIRunner            TUIRunner
	WebRunner            WebRunner
	SprintRuntimeFactory SprintRuntimeFactory
}

type classedError struct {
	class int
	code  string
	err   error
}

func (e classedError) Error() string { return e.err.Error() }
func (e classedError) Unwrap() error { return e.err }
func (e classedError) Code() string  { return e.code }

type displayError struct {
	display string
	cause   error
}

func (e displayError) Error() string { return e.display }
func (e displayError) Unwrap() error { return e.cause }

func classified(class int, format string, args ...any) error {
	return classedError{class: class, code: errorCode(class), err: fmt.Errorf(format, args...)}

package workspace

import (
	"fmt"
	"os"
	"path/filepath"
)

const MarkerFile = "ultraplan.yml"

type Root struct {
	Path string
}

type DiscoverOptions struct {
	ExplicitPath string
	EnvWorkspace string
	StartDir     string
}

func Discover(opts DiscoverOptions) (Root, error) {
	if opts.ExplicitPath != "" {
		return requireWorkspace(opts.ExplicitPath)
	}
	if opts.EnvWorkspace != "" {
		return requireWorkspace(opts.EnvWorkspace)
	}
	start := opts.StartDir
	if start == "" {
		var err error
		start, err = os.Getwd()
		if err != nil {
			return Root{}, fmt.Errorf("get working directory: %w", err)
		}
	}
	start, err := normalize(start)
	if err != nil {
		return Root{}, err
	}
	for {
		if HasMarker(start) {
			return Root{Path: start}, nil
		}
		parent := filepath.Dir(start)
		if parent == start {
			break
		}
		start = parent
	}
	return Root{}, fmt.Errorf("workspace not found: initialize one with 'ultraplan init-workspace'")
}

func requireWorkspace(path string) (Root, error) {
	root, err := normalize(path)
	if err != nil {
		return Root{}, err
	}
	if !HasMarker(root) {
		return Root{}, fmt.Errorf("invalid workspace %q: missing %s", root, MarkerFile)
	}
	return Root{Path: root}, nil
}

func HasMarker(root string) bool {
	info, err := os.Stat(filepath.Join(root, MarkerFile))
	return err == nil && !info.IsDir()
}

func normalize(path string) (string, error) {
	if path == "" {
		return "", fmt.Errorf("path is required")
	}
	abs, err := filepath.Abs(path)
	if err != nil {
		return "", fmt.Errorf("normalize path %q: %w", path, err)
	}
	return filepath.Clean(abs), nil
}

